local addonName = "WeakAuras"
local importText = "Open page"
local function frame()
    if private.g.mainFrame then
        private.pages:CreateWeakauraFrame(WAStrings,private.g.mainFrame.frame)
    end
    
end

local function frameTwink()
    if private.g.twinkFrame then
        private.pages:CreateWeakauraFrame(WAStrings,private.g.twinkFrame.frame)
    end
    
end

table.insert(private.Addons, {
    name = addonName,
    import = frame,
    importText = importText,
	importTwink = frameTwink
})